public class MyLoader extends ClassLoader {
  private final java.nio.file.Path dir;
  public MyLoader(java.nio.file.Path dir, ClassLoader parent){ super(parent); this.dir = dir; }

  @Override
  protected Class<?> findClass(String name) throws ClassNotFoundException {
    try {
      java.nio.file.Path p = dir.resolve(name.replace((char) 46, (char) 47) + ".class");
      byte[] bytes = java.nio.file.Files.readAllBytes(p);
      return defineClass(name, bytes, 0, bytes.length);   // 同一加载器同名只能一次
    } catch (java.io.IOException e) {
      throw new ClassNotFoundException(name, e);
    }
  }
}

